{
  "root": "main",
  "state": {
    "cities": [
      {
        "id": "rome",
        "city": "Rome, Italy",
        "avgHigh": "22°C",
        "avgLow": "12°C",
        "rainyDays": 8,
        "sunshine": 6,
        "image": "../assets/r_000009_01_1_rome_autumn.jpg"
      },
      {
        "id": "lisbon",
        "city": "Lisbon, Portugal",
        "avgHigh": "22°C",
        "avgLow": "15°C",
        "rainyDays": 9,
        "sunshine": 7,
        "image": "../assets/r_000009_01_2_lisbon_coast.jpg"
      }
    ],
    "tableColumns": [
      {
        "key": "city",
        "label": "City"
      },
      {
        "key": "avgHigh",
        "label": "Average High (°C)"
      },
      {
        "key": "avgLow",
        "label": "Average Low (°C)"
      },
      {
        "key": "rainyDays",
        "label": "Average Rainy Days"
      },
      {
        "key": "sunshine",
        "label": "Average Sunshine (Hours/Day)"
      }
    ]
  },
  "elements": {
    "main": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg",
        "padding": 16
      },
      "children": [
        "title",
        "intro",
        "note_card",
        "comparison_title",
        "cards_view",
        "table_title",
        "table_view",
        "recommendation_card",
        "gallery_title",
        "gallery_stack"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "October Climate Showdown: Rome vs. Lisbon",
        "variant": "h1"
      },
      "children": []
    },
    "intro": {
      "type": "Text",
      "props": {
        "text": "This comparison provides a snapshot of the typical weather conditions in Rome and Lisbon during October to help with your travel planning. It outlines key climate metrics to help you decide which city best suits your preference for warmer, sunnier weather."
      },
      "children": []
    },
    "note_card": {
      "type": "Card",
      "props": {},
      "children": [
        "note_stack"
      ]
    },
    "note_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm",
        "padding": 16
      },
      "children": [
        "note_title",
        "note_body"
      ]
    },
    "note_title": {
      "type": "Text",
      "props": {
        "text": "A Note on Climate Averages",
        "variant": "h3"
      },
      "children": []
    },
    "note_body": {
      "type": "Text",
      "props": {
        "text": "The following data is based on long-term historical climate averages and should be used as a general guide, not a live weather forecast. Actual weather conditions in October 2024 can vary. It is always recommended to check a detailed forecast closer to your travel dates."
      },
      "children": []
    },
    "comparison_title": {
      "type": "Text",
      "props": {
        "text": "October Weather Comparison",
        "variant": "h2"
      },
      "children": []
    },
    "cards_view": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "wrap": "wrap",
        "justify": "center"
      },
      "children": [
        "city_card_template"
      ]
    },
    "city_card_template": {
      "type": "Card",
      "repeat": {
        "statePath": "/cities",
        "key": "id"
      },
      "props": {
        "width": 320
      },
      "children": [
        "card_stack"
      ]
    },
    "card_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "none"
      },
      "children": [
        "card_image",
        "card_content_stack"
      ]
    },
    "card_image": {
      "type": "Image",
      "props": {
        "url": {
          "$item": "image"
        },
        "height": 180,
        "fit": "cover"
      },
      "children": []
    },
    "card_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "city_name",
        "metrics_stack"
      ]
    },
    "city_name": {
      "type": "Text",
      "props": {
        "text": {
          "$item": "city"
        },
        "variant": "h3"
      },
      "children": []
    },
    "metrics_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "metric_high",
        "metric_low",
        "metric_rain",
        "metric_sun"
      ]
    },
    "metric_high": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "center"
      },
      "children": [
        "icon_temp",
        "text_high"
      ]
    },
    "icon_temp": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000009_01_4_thermometer-half.svg"
      },
      "children": []
    },
    "text_high": {
      "type": "Text",
      "props": {
        "text": {
          "$template": "Avg. High: ${avgHigh}"
        }
      },
      "children": []
    },
    "metric_low": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "center"
      },
      "children": [
        "icon_temp",
        "text_low"
      ]
    },
    "text_low": {
      "type": "Text",
      "props": {
        "text": {
          "$template": "Avg. Low: ${avgLow}"
        }
      },
      "children": []
    },
    "metric_rain": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "center"
      },
      "children": [
        "icon_rain",
        "text_rain"
      ]
    },
    "icon_rain": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000009_01_6_cloud-rain-fill.svg"
      },
      "children": []
    },
    "text_rain": {
      "type": "Text",
      "props": {
        "text": {
          "$template": "Rainy Days: ${rainyDays}"
        }
      },
      "children": []
    },
    "metric_sun": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "center"
      },
      "children": [
        "icon_sun",
        "text_sun"
      ]
    },
    "icon_sun": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000009_01_5_sun-fill.svg"
      },
      "children": []
    },
    "text_sun": {
      "type": "Text",
      "props": {
        "text": {
          "$template": "Sunshine: ${sunshine} hrs/day"
        }
      },
      "children": []
    },
    "table_title": {
      "type": "Text",
      "props": {
        "text": "Comparison Data",
        "variant": "h2"
      },
      "children": []
    },
    "table_view": {
      "type": "Table",
      "props": {
        "statePath": "/cities",
        "columns": {
          "$state": "/tableColumns"
        },
        "domain": "weather",
        "preferredPresentation": "cards",
